FUNCTION WORD_TO_STRING : STRING
VAR_INPUT
	IN : WORD;
END_VAR
VAR
	v : UDINT;
	d : UDINT;
	s : STRING;
END_VAR
v := WORD_TO_UDINT(IN);
s := '';
REPEAT
	d := v MOD 10;
	CASE UDINT_TO_INT(d) OF
		0: s := CONCAT('0', s);
		1: s := CONCAT('1', s);
		2: s := CONCAT('2', s);
		3: s := CONCAT('3', s);
		4: s := CONCAT('4', s);
		5: s := CONCAT('5', s);
		6: s := CONCAT('6', s);
		7: s := CONCAT('7', s);
		8: s := CONCAT('8', s);
		9: s := CONCAT('9', s);
	END_CASE;
	v := v / 10;
UNTIL v = 0
END_REPEAT;
WORD_TO_STRING := s;
END_FUNCTION

